pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Restrict: caller can only be the initial owner (address(0) since never set) to avoid revert
        vm.assume(caller == address(0));

        // Precondition: no transferOwnership call, so owner is address(0)
        address ownerBefore = c.owner();

        // Drive through owned()
        vm.prank(caller);
        c.owned();

        // Assert: owner unchanged after owned()
        assertTrue(c.owner() == ownerBefore);
    }
}

