pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Set owner to a known non-zero address first
        vm.prank(c.owner());
        c.transferOwnership(address(1));
        // Now test: current owner calls transferOwnership with newOwner
        vm.prank(address(1));
        c.transferOwnership(newOwner);
        // Call owned()
        c.owned();
        // Assert: owner after owned() should be newOwner
        assertTrue(c.owner() == newOwner);
    }
}

