// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        // Set initial owner to this contract via prank
        vm.prank(address(this));
        c.transferOwnership(address(this));
        // Now call owned() as the current owner (this contract)
        vm.prank(address(this));
        // Wrap the call in try/catch to handle revert safely
        try c.owned() {
            // After owned() succeeds, transfer ownership to newOwner
            vm.prank(address(this));
            c.transferOwnership(newOwner);
            // Then call owned() again as the owner
            vm.prank(newOwner);
            try c.owned() {
                assertTrue(c.owner() == newOwner);
            } catch {
                assertTrue(false);
            }
        } catch {
            assertTrue(false);
        }
    }
}
